description:
Write `withTimeout(task, ms, outerSignal)`:

- `task` is a function that takes an `AbortSignal` and returns a promise;
- call it with a **new** signal that aborts when `ms` milliseconds pass **or** when `outerSignal` (optional) aborts, whichever comes first;
- resolve or reject as the task does; when the time runs out, reject with an `Error` whose `name` is `"TimeoutError"`; when the outer signal aborts, reject with its reason;
- clear the timer and remove listeners from `outerSignal` when it settles.

Do not use `AbortSignal.timeout` or `AbortSignal.any`: build it from an `AbortController`.

starter.solution.js:
function withTimeout(task, ms, outerSignal) {
  return task(new AbortController().signal);
}

solution.solution.js:
function withTimeout(task, ms, outerSignal) {
  const controller = new AbortController();
  const timeoutError = new Error(`timed out after ${ms} ms`);
  timeoutError.name = "TimeoutError";
  return new Promise((resolve, reject) => {
    const finish = () => {
      clearTimeout(timer);
      if (outerSignal) outerSignal.removeEventListener("abort", onOuter);
    };
    const onOuter = () => {
      finish();
      controller.abort(outerSignal.reason);
      reject(outerSignal.reason);
    };
    const timer = setTimeout(() => {
      finish();
      controller.abort(timeoutError);
      reject(timeoutError);
    }, ms);
    if (outerSignal) {
      if (outerSignal.aborted) {
        onOuter();
        return;
      }
      outerSignal.addEventListener("abort", onOuter, { once: true });
    }
    Promise.resolve()
      .then(() => task(controller.signal))
      .then(
        value => { finish(); resolve(value); },
        error => { finish(); reject(error); },
      );
  });
}

unitTests:
function work(ms, value) {
  return signal => new Promise((resolve, reject) => {
    const t = setTimeout(() => resolve(value), ms);
    signal.addEventListener("abort", () => { clearTimeout(t); reject(signal.reason); }, { once: true });
  });
}

test("a fast task resolves", async () => {
  checkEq(await withTimeout(work(10, "done"), 200), "done");
});

test("a slow task times out", async () => {
  let err = null;
  try {
    await withTimeout(work(500, "late"), 20);
  } catch (e) {
    err = e;
  }
  checkEq(err && err.name, "TimeoutError");
});

test("the task's signal is aborted on timeout", async () => {
  let seen = null;
  try {
    await withTimeout(signal => { seen = signal; return new Promise(() => {}); }, 20);
  } catch (e) {}
  checkEq(seen.aborted, true);
});

test("the outer signal cancels with its reason", async () => {
  const c = new AbortController();
  setTimeout(() => c.abort("user"), 10);
  let err = null;
  try {
    await withTimeout(work(500, "x"), 1000, c.signal);
  } catch (e) {
    err = e;
  }
  checkEq(err, "user");
});

test("task errors pass through", async () => {
  let err = null;
  try {
    await withTimeout(async () => { throw new TypeError("bad"); }, 100);
  } catch (e) {
    err = e;
  }
  check(err instanceof TypeError);
});

